package org.bukkit.event.entity;
public class PotionSplashEvent extends org.bukkit.event.Event implements org.bukkit.event.Cancellable {
 private final org.bukkit.entity.ThrownPotion potion;private final java.util.Map<org.bukkit.entity.LivingEntity,Double> intensities;private boolean cancelled;
 public PotionSplashEvent(org.bukkit.entity.ThrownPotion potion,java.util.Map<org.bukkit.entity.LivingEntity,Double> intensities){this.potion=java.util.Objects.requireNonNull(potion);this.intensities=new java.util.LinkedHashMap<>(intensities);}public org.bukkit.entity.ThrownPotion getPotion(){return potion;}public java.util.Collection<org.bukkit.entity.LivingEntity> getAffectedEntities(){return java.util.Collections.unmodifiableSet(intensities.keySet());}public double getIntensity(org.bukkit.entity.LivingEntity entity){return intensities.getOrDefault(entity,0.0);}public void setIntensity(org.bukkit.entity.LivingEntity entity,double value){if(!Double.isFinite(value)||value<0||value>1)throw new IllegalArgumentException("Сила зелья: конечное число 0..1");if(!intensities.containsKey(entity))throw new IllegalArgumentException("Сущность вне области зелья");intensities.put(entity,value);}public boolean isCancelled(){return cancelled;}public void setCancelled(boolean value){cancelled=value;}
}
